import { Box, Grid } from "@mui/material";

import WeatherIntelligence from "./WeatherIntelligence";
import ForecastStatistics from "./ForecastStatistics";
import ForecastTrendChart from "./ForecastTrendChart";
import ScenarioTrendChart from "./ScenarioTrendChart";
import StockpileTrajectory from "./StockpileTrajectory";
import ForecastInsights from "./ForecastInsights";
import ScenarioComparison from "./ScenarioComparison";
import WeatherCorrelation from "./WeatherCorrelation";
import StationFleetOverview from "./StationFleetOverview";

import { useForecastContext } from "../../../contexts/ForecastContext";
import { ForecastFilters } from "../types/forecast.types";

/**
 * =====================================================
 * FORECAST OVERVIEW  (REDESIGNED / REGROUPED)
 * =====================================================
 * Completely re-arranged so the page reads like a modern
 * operations dashboard. Every grid cell is a stretch-flex
 * container so cards in the same row share equal heights.
 *
 *  1. KPI ticker row (animated)
 *  2. Hero: forecast trend  +  live weather intelligence
 *  3. Stockpile trajectory + derived insights
 *  4. Scenario comparison  +  scenario trend
 *  5. Station fleet  +  weather correlation
 */
const ForecastOverview = () => {
  const { horizon, metric, entityId, scenario } = useForecastContext();

  const filters: ForecastFilters = { horizon, metric, entityId, scenario };

  return (
    <Box sx={{ width: "100%", minWidth: 0 }}>
      {/* 1 · KPI ticker */}
      <Box sx={{ mb: 3 }}>
        <ForecastStatistics />
      </Box>

      {/* 2 · Hero trend (full width) */}
      <Box sx={{ mb: 2.5 }}>
        <Box className="eskom-fade-up">
          <ForecastTrendChart filters={filters} />
        </Box>
      </Box>

      {/* 3 · Weather Intelligence (full width, better visibility) */}
      <Box sx={{ mb: 2.5 }}>
        <Box className="eskom-fade-up">
          <WeatherIntelligence entityId={entityId} />
        </Box>
      </Box>

      {/* 4 · Stockpile trajectory + insights */}
      <Grid container spacing={2.5} sx={{ mb: 2.5 }}>
        <Grid item xs={12} xl={7} sx={{ display: "flex" }}>
          <Box className="eskom-fade-up" sx={{ flex: 1, minWidth: 0 }}>
            <StockpileTrajectory filters={filters} />
          </Box>
        </Grid>
        <Grid item xs={12} xl={5} sx={{ display: "flex" }}>
          <Box className="eskom-fade-up" sx={{ flex: 1, minWidth: 0 }}>
            <ForecastInsights filters={filters} />
          </Box>
        </Grid>
      </Grid>

      {/* 5 · Scenario comparison + scenario trend */}
      <Grid container spacing={2.5} sx={{ mb: 2.5 }}>
        <Grid item xs={12} lg={4} sx={{ display: "flex" }}>
          <Box className="eskom-fade-up" sx={{ flex: 1, minWidth: 0 }}>
            <ScenarioComparison filters={filters} />
          </Box>
        </Grid>
        <Grid item xs={12} lg={8} sx={{ display: "flex" }}>
          <Box className="eskom-fade-up" sx={{ flex: 1, minWidth: 0 }}>
            <ScenarioTrendChart filters={filters} />
          </Box>
        </Grid>
      </Grid>

      {/* 5 · Station fleet + weather correlation */}
      <Grid container spacing={2.5}>
        <Grid item xs={12} lg={4} sx={{ display: "flex" }}>
          <Box className="eskom-fade-up" sx={{ flex: 1, minWidth: 0 }}>
            <StationFleetOverview />
          </Box>
        </Grid>
        <Grid item xs={12} lg={8} sx={{ display: "flex" }}>
          <Box className="eskom-fade-up" sx={{ flex: 1, minWidth: 0 }}>
            <WeatherCorrelation filters={filters} />
          </Box>
        </Grid>
      </Grid>
    </Box>
  );
};

export default ForecastOverview;
